E = []
def add(id, name, type, task, license, commercial, url, how="linked", notes="", size="", license_source="", fetch=None):
    E.append(dict(id=id, name=name, type=type, task=task, license=license, commercial=commercial,
                  how=how, url=url, size=size, license_source=license_source or "repository licence field / model card", notes=notes, **({"fetch": fetch} if fetch else {})))

